(* Types *)

let residue_TYBIJ = new_type_definition "residue" ("mk_residue",
 "dest_residue")
  (prove(`?(f:A->num). !(p:A) (q:A). f p = f q`,
   EXISTS_TAC `\(p:A). (ARB:num)` THEN REWRITE_TAC[]));;

let Residue_DEF = new_definition
  `Residue (x:num) = (mk_residue (\(p:A). x):(A)residue)`;;

let residue_rep_DEF = new_definition
  `residue_rep (r:(A)residue) = dest_residue r (ARB:A)`;;

let residue_SEL_CTR, residue_CTR_SEL, residue_INJECT =
  fips_phantom_theorems residue_TYBIJ Residue_DEF residue_rep_DEF;;

let fips203_zq_INDUCT, fips203_zq_RECURSION = define_type
  "fips203_zq = FIPS203_Zq ((3329)residue)";;

let fault_INDUCT, fault_RECURSION = define_type
  "fault = Explicit_Abort
    | Bounds_Error";;

let native_result_INDUCT, native_result_RECURSION = define_type
  "native_result = Value (A)
    | Fault (fault)
    | Nontermination";;

let aop_INDUCT, aop_RECURSION = define_type
  "aop = AAdd
    | ASub
    | AMul
    | ADiv
    | AQuot
    | AMod
    | APow";;

let common_vec_TYBIJ = new_type_definition "common_vec" ("mk_common_vec",
 "dest_common_vec")
  (prove(`?(f:A->(B)list). !(p:A) (q:A). f p = f q`,
   EXISTS_TAC `\(p:A). (ARB:(B)list)` THEN REWRITE_TAC[]));;

let Common_Vec_DEF = new_definition
  `Common_Vec (x:(B)list) = (mk_common_vec (\(p:A). x):(A,B)common_vec)`;;

let common_vec_entries_DEF = new_definition
  `common_vec_entries (r:(A,B)common_vec) = dest_common_vec r (ARB:A)`;;

let common_vec_SEL_CTR, common_vec_CTR_SEL, common_vec_INJECT =
  fips_phantom_theorems common_vec_TYBIJ Common_Vec_DEF
   common_vec_entries_DEF;;

let fips203_poly_TYBIJ = new_type_definition "fips203_poly"
 ("mk_fips203_poly", "dest_fips203_poly")
  (prove(`?(f:A->(fips203_zq)list). !(p:A) (q:A). f p = f q`,
   EXISTS_TAC `\(p:A). (ARB:(fips203_zq)list)` THEN REWRITE_TAC[]));;

let FIPS203_Poly_DEF = new_definition
  `FIPS203_Poly (x:(fips203_zq)list) =
     (mk_fips203_poly (\(p:A). x):(A)fips203_poly)`;;

let fips203_poly_coefficients_DEF = new_definition
  `fips203_poly_coefficients (r:(A)fips203_poly) =
     dest_fips203_poly r (ARB:A)`;;

let fips203_poly_SEL_CTR, fips203_poly_CTR_SEL, fips203_poly_INJECT =
  fips_phantom_theorems fips203_poly_TYBIJ FIPS203_Poly_DEF
   fips203_poly_coefficients_DEF;;

let fips203_ntt_INDUCT, fips203_ntt_RECURSION = define_type
  "fips203_ntt = FIPS203_NTT";;

let fips203_time_INDUCT, fips203_time_RECURSION = define_type
  "fips203_time = FIPS203_Time";;

let xof_phase_INDUCT, xof_phase_RECURSION = define_type
  "xof_phase = Absorbing
    | Squeezing";;

let surface_fault_INDUCT, surface_fault_RECURSION = define_type
  "surface_fault = Type_Error
    | Arithmetic_Error
    | Range_Error
    | Index_Error
    | Unassigned_Error (isa_literal)
    | Abort_Error
    | Bottom_Error";;

let iteration_outcome_INDUCT, iteration_outcome_RECURSION = define_type
  "iteration_outcome = Finished (B)
    | Again (A)";;

let fips_matrix_TYBIJ = new_type_definition "fips_matrix" ("mk_fips_matrix",
 "dest_fips_matrix")
  (prove(`?(f:(A#B)->(C)list). !(p:(A#B)) (q:(A#B)). f p = f q`,
   EXISTS_TAC `\(p:(A#B)). (ARB:(C)list)` THEN REWRITE_TAC[]));;

let FIPS_Matrix_DEF = new_definition
  `FIPS_Matrix (x:(C)list) =
     (mk_fips_matrix (\(p:(A#B)). x):(A,B,C)fips_matrix)`;;

let fips_matrix_entries_DEF = new_definition
  `fips_matrix_entries (r:(A,B,C)fips_matrix) =
     dest_fips_matrix r (ARB:(A#B))`;;

let fips_matrix_SEL_CTR, fips_matrix_CTR_SEL, fips_matrix_INJECT =
  fips_phantom_theorems fips_matrix_TYBIJ FIPS_Matrix_DEF
   fips_matrix_entries_DEF;;

let common_mat_INDUCT, common_mat_RECURSION = define_type
  "common_mat = Common_Mat ((A,B,C)fips_matrix)";;

let native_bottom_INDUCT, native_bottom_RECURSION = define_type
  "native_bottom = Native_Bottom
    | Native_Value (A)";;

(* Constants *)

let residue_of_int_mod_DEF = new_definition
  `!(v:int).
   residue_of_int_mod v =
     ((Residue:(num->(Q)residue))
      (isa_nat (isa_int_mod v (int_of_num (dimindex(:Q))))))`;;

let fips203_zq_residue_DEF = new_recursive_definition fips203_zq_RECURSION
  `(!(x:(3329)residue). ((fips203_zq_residue (FIPS203_Zq x)) = x))`;;

let BaseCaseMultiply_hol_DEF = new_definition
  `!(a0:fips203_zq) (a1:fips203_zq) (b0:fips203_zq) (b1:fips203_zq)
     (gamma:fips203_zq).
   BaseCaseMultiply_hol a0 a1 b0 b1 gamma =
     (let (v:(3329)residue) =
        ((residue_of_int_mod:(int->(3329)residue))
         (int_mul
          (int_of_num (residue_rep (fips203_zq_residue a0)))
          (int_of_num (residue_rep (fips203_zq_residue b0))))) in
      (let (va:(3329)residue) =
         ((residue_of_int_mod:(int->(3329)residue))
          (int_mul
           (int_of_num (residue_rep (fips203_zq_residue a1)))
           (int_of_num (residue_rep (fips203_zq_residue b1))))) in
       (let (vb:(3329)residue) =
          ((residue_of_int_mod:(int->(3329)residue))
           (int_mul
            (int_of_num (residue_rep va))
            (int_of_num (residue_rep (fips203_zq_residue gamma))))) in
        (let (native_0:(3329)residue) =
           ((residue_of_int_mod:(int->(3329)residue))
            (int_add
             (int_of_num (residue_rep v))
             (int_of_num (residue_rep vb)))) in
         (let (vc:(3329)residue) =
            ((residue_of_int_mod:(int->(3329)residue))
             (int_mul
              (int_of_num (residue_rep (fips203_zq_residue a0)))
              (int_of_num (residue_rep (fips203_zq_residue b1))))) in
          (let (vd:(3329)residue) =
             ((residue_of_int_mod:(int->(3329)residue))
              (int_mul
               (int_of_num (residue_rep (fips203_zq_residue a1)))
               (int_of_num (residue_rep (fips203_zq_residue b0))))) in
           (let (native_1:(3329)residue) =
              ((residue_of_int_mod:(int->(3329)residue))
               (int_add
                (int_of_num (residue_rep vc))
                (int_of_num (residue_rep vd)))) in
            (let (native_3:fips203_zq) = (FIPS203_Zq native_0) in
             (let (native_4:fips203_zq) = (FIPS203_Zq native_1) in
              (Value (native_3,native_4)))))))))))`;;

let case_native_result_DEF = new_recursive_definition native_result_RECURSION
  `(!(f1:(A->B)) (f2:(fault->B)) (f3:B) (x1:A).
    ((case_native_result f1 f2 f3 (Value x1)) = (f1 x1))) /\
   (!(f1:(A->B)) (f2:(fault->B)) (f3:B) (x2:fault).
    ((case_native_result f1 f2 f3 ((Fault:(fault->(A)native_result)) x2)) =
     (f2 x2))) /\
   (!(f1:(A->B)) (f2:(fault->B)) (f3:B).
    ((case_native_result f1 f2 f3 (Nontermination:(A)native_result)) = f3))`;;

let native_bind_DEF = new_definition
  `!(answer:(A)native_result) (rest:(A->(B)native_result)).
   native_bind answer rest =
     (case_native_result
      (\(value:A). (rest value))
      (\(failure:fault). ((Fault:(fault->(B)native_result)) failure))
      (Nontermination:(B)native_result)
      answer)`;;

let native_foldl_DEF = new_recursive_definition list_RECURSION
  `(!(body:(I->(S->(S)native_result))) (s:S).
    ((native_foldl body ([]:(I)list) s) = (Value s))) /\
   (!(body:(I->(S->(S)native_result))) (i:I) (indices:(I)list) (s:S).
    ((native_foldl body (CONS i indices) s) =
     (native_bind (body i s) (native_foldl body indices))))`;;

let arith_faults_DEF = new_definition
  `!(op:aop) (zero:bool) (below:bool) (inexact:bool).
   arith_faults op zero below inexact =
     ((((op = ADiv) \/ ((op = AQuot) \/ (op = AMod))) /\ zero) \/
      (((op = AMod) /\ below) \/ ((op = AQuot) /\ inexact)))`;;

let case_aop_DEF = new_recursive_definition aop_RECURSION
  `(!(f1:A) (f2:A) (f3:A) (f4:A) (f5:A) (f6:A) (f7:A).
    ((case_aop f1 f2 f3 f4 f5 f6 f7 AAdd) = f1)) /\
   (!(f1:A) (f2:A) (f3:A) (f4:A) (f5:A) (f6:A) (f7:A).
    ((case_aop f1 f2 f3 f4 f5 f6 f7 ASub) = f2)) /\
   (!(f1:A) (f2:A) (f3:A) (f4:A) (f5:A) (f6:A) (f7:A).
    ((case_aop f1 f2 f3 f4 f5 f6 f7 AMul) = f3)) /\
   (!(f1:A) (f2:A) (f3:A) (f4:A) (f5:A) (f6:A) (f7:A).
    ((case_aop f1 f2 f3 f4 f5 f6 f7 ADiv) = f4)) /\
   (!(f1:A) (f2:A) (f3:A) (f4:A) (f5:A) (f6:A) (f7:A).
    ((case_aop f1 f2 f3 f4 f5 f6 f7 AQuot) = f5)) /\
   (!(f1:A) (f2:A) (f3:A) (f4:A) (f5:A) (f6:A) (f7:A).
    ((case_aop f1 f2 f3 f4 f5 f6 f7 AMod) = f6)) /\
   (!(f1:A) (f2:A) (f3:A) (f4:A) (f5:A) (f6:A) (f7:A).
    ((case_aop f1 f2 f3 f4 f5 f6 f7 APow) = f7))`;;

let int_op_DEF = new_definition
  `!(op:aop) (a:int) (b:int).
   int_op op a b =
     (case_aop
      (int_add a b)
      (int_sub a b)
      (int_mul a b)
      (isa_int_div a b)
      (isa_int_div a b)
      (isa_int_mod a b)
      (int_pow a (isa_nat b))
      op)`;;

let typed_hol_int_arithmetic_DEF = new_definition
  `!(op:aop) (a:int) (b:int).
   typed_hol_int_arithmetic op a b =
     (if (op = APow)
      then (if (int_lt b (&0:int))
            then ((Fault:(fault->(int)native_result)) Bounds_Error)
            else (Value (int_pow a (isa_nat b))))
      else (if (arith_faults
                op
                (b = (&0:int))
                (int_lt b (&0:int))
                (~((isa_int_mod a b) = (&0:int))))
            then ((Fault:(fault->(int)native_result)) Bounds_Error)
            else (Value (int_op op a b))))`;;

let BitRev7_hol_DEF = new_definition
  `!(r:int).
   BitRev7_hol r =
     (native_foldl
      (\(j:int).
       (\(acc:int).
        (let (v:int) = (int_pow (&2:int) (isa_nat j)) in
         (native_bind
          (typed_hol_int_arithmetic ADiv r v)
          (\(va:int).
           (let (vb:int) = (isa_int_mod va (&2:int)) in
            (let (vc:int) = (int_sub (&6:int) j) in
             (native_bind
              (typed_hol_int_arithmetic APow (&2:int) vc)
              (\(value:int).
               (let (vd:int) = (int_mul vb value) in
                (Value (int_add acc vd))))))))))))
      (CONS
       (&0:int)
       (CONS
        (&1:int)
        (CONS
         (&2:int)
         (CONS
          (&3:int)
          (CONS (&4:int) (CONS (&5:int) (CONS (&6:int) ([]:(int)list))))))))
      (&0:int))`;;

let typed_hol_int_to_byte_DEF = new_definition
  `!(n:int).
   typed_hol_int_to_byte n =
     (if ((int_le (&0:int) n) /\ (int_lt n (&256:int)))
      then (Value (iword n:(8)word))
      else ((Fault:(fault->((8)word)native_result)) Bounds_Error))`;;

let typed_hol_read_DEF = new_definition
  `!(r:(A)option).
   typed_hol_read r =
     (isa_case_option
      ((Fault:(fault->(A)native_result)) Bounds_Error)
      (\(x:A). (Value x))
      r)`;;

let native_list_index_DEF = new_definition
  `!(xs:(A)list) (i:int).
   native_list_index xs i =
     (if ((int_le (&0:int) i) /\ (int_lt i (int_of_num (LENGTH xs))))
      then (SOME (EL (isa_nat i) xs))
      else (NONE:(A)option))`;;

let typed_hol_byte_value_DEF = new_definition
  `!(b:(8)word). typed_hol_byte_value b = (Value (int_of_num (val b)))`;;

let typed_hol_bit_value_DEF = new_definition
  `!(b:bool).
   typed_hol_bit_value b = (Value (if b then (&1:int) else (&0:int)))`;;

let native_list_update_DEF = new_definition
  `!(xs:(A)list) (i:int) (a:A).
   native_list_update xs i a =
     (if ((int_le (&0:int) i) /\ (int_lt i (int_of_num (LENGTH xs))))
      then (SOME (isa_list_update xs (isa_nat i) a))
      else (NONE:((A)list)option))`;;

let native_schedule_DEF = new_recursive_definition num_RECURSION
  `(!(guard:(I->bool)) (next:(I->I)) (i:I).
    ((native_schedule 0 guard next i) = ([]:(I)list))) /\
   (!(n:num) (guard:(I->bool)) (next:(I->I)) (i:I).
    ((native_schedule (SUC n) guard next i) =
     (if (guard i)
      then (CONS i (native_schedule n guard next (next i)))
      else ([]:(I)list))))`;;

let BitsToBytes_32_hol_DEF = new_definition
  `!(b:(bool)list).
   BitsToBytes_32_hol b =
     (native_bind
      (typed_hol_int_to_byte (&0:int))
      (\(v:(8)word).
       (let (va:((8)word)list) = (REPLICATE 32 v) in
        (native_foldl
         (\(i:int).
          (\(B:((8)word)list).
           (native_bind
            (typed_hol_int_arithmetic ADiv i (&8:int))
            (\(vb:int).
             (native_bind
              (typed_hol_int_arithmetic ADiv i (&8:int))
              (\(vc:int).
               (native_bind
                (typed_hol_read (native_list_index B vc))
                (\(vd:(8)word).
                 (native_bind
                  (typed_hol_byte_value vd)
                  (\(ve:int).
                   (native_bind
                    (typed_hol_read (native_list_index b i))
                    (\(vf:bool).
                     (native_bind
                      (typed_hol_bit_value vf)
                      (\(vg:int).
                       (let (vh:int) = (isa_int_mod i (&8:int)) in
                        (native_bind
                         (typed_hol_int_arithmetic APow (&2:int) vh)
                         (\(vi:int).
                          (let (vj:int) = (int_mul vg vi) in
                           (let (vk:int) = (int_add ve vj) in
                            (native_bind
                             (typed_hol_int_to_byte vk)
                             (\(vl:(8)word).
                              (typed_hol_read
                               (native_list_update
                                B
                                vb
                                vl)))))))))))))))))))))))
         (native_schedule
          257
          (\(i:int). (int_lt i (&256:int)))
          (\(i:int). (int_add i (&1:int)))
          (&0:int))
         va))))`;;

