let source_fault_DEF = new_recursive_definition surface_fault_RECURSION
  `(((source_fault Abort_Error) = Explicit_Abort)) /\
   (((source_fault Type_Error) = Bounds_Error)) /\
   (((source_fault Arithmetic_Error) = Bounds_Error)) /\
   (((source_fault Range_Error) = Bounds_Error)) /\
   (((source_fault Index_Error) = Bounds_Error)) /\
   (!(v:isa_literal). ((source_fault (Unassigned_Error v)) = Bounds_Error)) /\
   (((source_fault Bottom_Error) = Bounds_Error))`;;

new_type_abbrev("ty_prod_1", `:(((8)word)list#(xof_phase#num))`);;

let XOF_Absorb_semantic_DEF = new_definition
  `XOF_Absorb_semantic =
     (UNCURRY
      (UNCURRY
       (\(input:((8)word)list).
        (UNCURRY
         (\(phase:xof_phase).
          (\(offset:num).
           (\(block:((8)word)list).
            (if (phase = Absorbing)
             then (Value ((APPEND input block),(phase,offset)))
             else ((Fault:(fault->(ty_prod_1)native_result))
                   (source_fault Range_Error))))))))))`;;

let case_iteration_outcome_DEF = new_recursive_definition iteration_outcome_RECURSION
  `(!(f1:(A->B)) (f2:(S->B)) (x1:A).
    ((case_iteration_outcome
      f1
      f2
      ((Finished:(A->(S,A)iteration_outcome)) x1)) =
     (f1 x1))) /\
   (!(f1:(A->B)) (f2:(S->B)) (x2:S).
    ((case_iteration_outcome f1 f2 ((Again:(S->(S,A)iteration_outcome)) x2)) =
     (f2 x2)))`;;

let hol_light_iterate_DEF = new_recursive_definition num_RECURSION
  `(!(step:(S->((S,A)iteration_outcome)native_result)) (s:S).
    ((hol_light_iterate 0 step s) = (Nontermination:(A)native_result))) /\
   (!(n:num) (step:(S->((S,A)iteration_outcome)native_result)) (s:S).
    ((hol_light_iterate (SUC n) step s) =
     (case_native_result
      (\(a:(S,A)iteration_outcome).
       (case_iteration_outcome
        (\(answer:A). (Value answer))
        (\(next:S). (hol_light_iterate n step next))
        a))
      (\(f:fault). ((Fault:(fault->(A)native_result)) f))
      (Nontermination:(A)native_result)
      (step s))))`;;

let native_iter_DEF = new_definition
  `!(step:(S->((S,A)iteration_outcome)native_result)) (s:S).
   native_iter step s =
     (if (?(n:num).
          (~((hol_light_iterate n step s) =
             (Nontermination:(A)native_result))))
      then (hol_light_iterate
            (@(n:num).
             (~((hol_light_iterate n step s) =
                (Nontermination:(A)native_result))))
            step
            s)
      else (Nontermination:(A)native_result))`;;

let map_native_result_DEF = new_recursive_definition native_result_RECURSION
  `(!(f:(A->AA)) (x1:A).
    ((map_native_result f (Value x1)) = (Value (f x1)))) /\
   (!(f:(A->AA)) (x2:fault).
    ((map_native_result f ((Fault:(fault->(A)native_result)) x2)) =
     ((Fault:(fault->(AA)native_result)) x2))) /\
   (!(f:(A->AA)).
    ((map_native_result f (Nontermination:(A)native_result)) =
     (Nontermination:(AA)native_result)))`;;

let native_loop_step_DEF = new_definition
  `!(test:(S->(bool)native_result)) (body:(S->(S)native_result)) (s:S).
   native_loop_step test body s =
     (native_bind
      (test s)
      (\(b:bool).
       (if b
        then (map_native_result (Again:(S->(S,S)iteration_outcome)) (body s))
        else (Value ((Finished:(S->(S,S)iteration_outcome)) s)))))`;;

let native_loop_DEF = new_definition
  `!(test:(S->(bool)native_result)) (body:(S->(S)native_result)).
   native_loop test body = (native_iter (native_loop_step test body))`;;

